Method.Implementation:
// get an instance of JMSGateway and connect to JMSGateway Super Serve #dim tStat As Status set tStat = $$$OK
Set jmsgateway=##class(EnsLib.JavaGateway.JavaGateway).%New() Set classPath=##class(%ListOfDataTypes).%New() Do classPath.Insert(..JMSJarPath) $$$LOGINFO("Added: " _ ..JMSJarPath) /* For n=1:1:$L(..JMSJarPath,":") { set pth = $P(..JMSJarPath,":",n) Do classPath.Insert(pth) $$$LOGINFO("Added file: " _ pth) } */
Set status=jmsgateway.%Connect(..JavaGWHost,..JavaGWPort,$NAMESPACE,5,classPath) If 'status Quit $$$ISERR(status) $$$LOGINFO("Connected to Java Gateway: " _ ..JavaGWHost _":"_..JavaGWPort)
try {
set tcf = ##class(com.seebeyond.jms.client.STCTopicConnectionFactory).%New(jmsgateway,..JMSHost, ..JMSPort) $$$LOGINFO("Connected to JMS: " _ ..JMSHost_":"_..JMSPort) set topicConnection = tcf.createTopicConnection() do topicConnection.start() $$$LOGINFO("JMS start")
set topicSession = topicConnection.createTopicSession(1, 1) //"true","Session.AUTO_ACKNOWLEDGE") $$$LOGINFO("created topicSession") set topic = topicSession.createTopic(..TopicName) $$$LOGINFO("created topic") set topicPublisher = topicSession.createPublisher(topic)
set message = topicSession.createTextMessage() do message.setText(pRequest.OutputToString()) $$$LOGINFO("JMS msg created") do topicPublisher.publish(message) $$$LOGINFO("JMS published") do topicSession.commit() do topicConnection.close()
Do jmsgateway.%Disconnect()
} catch err { set lstErr = $GET(%objlasterror) if (lstErr '= "") { set errMsg = $System.Status.GetErrorText(%objlasterror) } else { set errMsg = "ERROR" } Do jmsgateway.%Disconnect()
$$$LOGERROR("Exception: Name: " _ err.Name _ " / Location:" _ err.Location _ " / Data: " _err.Data _ " / Details: " _ errMsg) set tStat = $$$ERROR($$$GeneralError, "Exception: Name: " _ err.Name) } Quit tStat
